70.full_solution:
Algorithme SpiraleMatrice;
Var
    N, M, I, J, Top, Bottom, Left, Right, K : Entier;
    Mat[50][50] : Entier;
Debut
    Lire(N);
    Lire(M);
    Pour I <- 0 a N - 1 Faire
        Pour J <- 0 a M - 1 Faire
            Lire(Mat[I][J]);
        FinPour;
    FinPour;
    Top <- 0;
    Bottom <- N - 1;
    Left <- 0;
    Right <- M - 1;
    TantQue (Top <= Bottom) ET (Left <= Right) Faire
        Pour J <- Left a Right Faire
            Ecrire(Mat[Top][J]);
        FinPour;
        Top <- Top + 1;
        Pour I <- Top a Bottom Faire
            Ecrire(Mat[I][Right]);
        FinPour;
        Right <- Right - 1;
        Si Top <= Bottom Alors
            K <- Right;
            TantQue K >= Left Faire
                Ecrire(Mat[Bottom][K]);
                K <- K - 1;
            FinTantQue;
            Bottom <- Bottom - 1;
        FinSi;
        Si Left <= Right Alors
            K <- Bottom;
            TantQue K >= Top Faire
                Ecrire(Mat[K][Left]);
                K <- K - 1;
            FinTantQue;
            Left <- Left + 1;
        FinSi;
    FinTantQue;
Fin.

