Algorithme TripletsSommeNulle;
Var
    N, I, J, Temp, Gauche, Droite, Somme, NbTriplets : Entier;
    T[1000] : Entier;
Debut
    Lire(N);
    Pour I <- 0 a N - 1 Faire
        Lire(T[I]);
    FinPour;

    // Tri a bulles / selection
    Pour I <- 0 a N - 2 Faire
        Pour J <- I + 1 a N - 1 Faire
            Si T[I] > T[J] Alors
                Temp <- T[I];
                T[I] <- T[J];
                T[J] <- Temp;
            FinSi;
        FinPour;
    FinPour;

    NbTriplets <- 0;
    Pour I <- 0 a N - 3 Faire
        Si (I = 0) OU (T[I] <> T[I - 1]) Alors
            Gauche <- I + 1;
            Droite <- N - 1;
            TantQue Gauche < Droite Faire
                Somme <- T[I] + T[Gauche] + T[Droite];
                Si Somme = 0 Alors
                    NbTriplets <- NbTriplets + 1;
                    Gauche <- Gauche + 1;
                    Droite <- Droite - 1;
                    TantQue (Gauche < Droite) ET (T[Gauche] = T[Gauche - 1]) Faire
                        Gauche <- Gauche + 1;
                    FinTantQue;
                    TantQue (Gauche < Droite) ET (T[Droite] = T[Droite + 1]) Faire
                        Droite <- Droite - 1;
                    FinTantQue;
                Sinon
                    Si Somme < 0 Alors
                        Gauche <- Gauche + 1;
                    Sinon
                        Droite <- Droite - 1;
                    FinSi;
                FinSi;
            FinTantQue;
        FinSi;
    FinPour;

    Ecrire(NbTriplets);
Fin.

